# Create the transform function - find background 1s with shape 9s above and below
# Background=1, Shape=9, Fill=4

def transform(grid):
    result = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    for c in range(w):
        # Get the column values
        col_vals = [grid[r][c] for r in range(h)]

        # Find sequences of 1s (background) that are followed by 9s (shape) at the end
        # Pattern: non-1s, then >=2 1s, then more 1s ending before non-1s or at end
        ones_seq = []
        bg_count = 0
        bg_start = None

        for r in range(h):
            if col_vals[r] == 1 and bg_count == 0:
                # Start of ones sequence
                bg_start = r
                bg_count = 1
            elif col_vals[r] == 1 and bg_count > 0:
                # Continue ones sequence
                bg_count += 1
            elif col_vals[r] != 1 and bg_count > 0:
                # Check if we should fill
                # Fill if there are shape cells that "bookend" this sequence
                # In the demo: ends need to bookend, so we need 9s below
                if ones_seq and len(ones_seq) >= 2:
                    for filled_r in range(bg_start, r):
                        if col_vals[filled_r] == 1:
                            result[filled_r][c] = 4
                ones_seq = []
                bg_count = 0
            else:
                ones_seq = []
                bg_count = 0

        # Handle sequence that goes to end of column
        if ones_seq and bg_count > 0:
            for filled_r in range(bg_start, h):
                if col_vals[filled_r] == 1:
                    result[filled_r][c] = 4

    return result

